CREATE DATABASE IF NOT EXISTS online_exam_ai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE online_exam_ai;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student') NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,enrollment_no VARCHAR(50) UNIQUE NOT NULL,student_name VARCHAR(150) NOT NULL,email VARCHAR(150) UNIQUE,course VARCHAR(100),semester VARCHAR(50),photo VARCHAR(255),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE teachers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,teacher_name VARCHAR(150) NOT NULL,email VARCHAR(150) UNIQUE,department VARCHAR(100),photo VARCHAR(255),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,subject_code VARCHAR(50) UNIQUE NOT NULL,subject_name VARCHAR(150) NOT NULL,status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE questions(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,teacher_id INT NOT NULL,question_text TEXT NOT NULL,question_type ENUM('mcq','descriptive') NOT NULL,difficulty ENUM('easy','medium','hard') DEFAULT 'medium',marks DECIMAL(5,2) NOT NULL,model_answer TEXT,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,FOREIGN KEY(teacher_id) REFERENCES teachers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE question_options(id INT AUTO_INCREMENT PRIMARY KEY,question_id INT NOT NULL,option_label ENUM('A','B','C','D') NOT NULL,option_text VARCHAR(500) NOT NULL,is_correct TINYINT(1) DEFAULT 0,UNIQUE(question_id,option_label),FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE exams(id INT AUTO_INCREMENT PRIMARY KEY,subject_id INT NOT NULL,teacher_id INT NOT NULL,exam_title VARCHAR(200) NOT NULL,instructions TEXT,total_marks DECIMAL(7,2) DEFAULT 0,duration_minutes INT NOT NULL,start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,negative_marking TINYINT(1) DEFAULT 0,negative_marks DECIMAL(5,2) DEFAULT 0,status ENUM('draft','scheduled','active','completed','cancelled') DEFAULT 'draft',FOREIGN KEY(subject_id) REFERENCES subjects(id),FOREIGN KEY(teacher_id) REFERENCES teachers(id)) ENGINE=InnoDB;
CREATE TABLE exam_questions(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT NOT NULL,question_id INT NOT NULL,question_order INT NOT NULL,marks DECIMAL(5,2) NOT NULL,UNIQUE(exam_id,question_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE exam_attempts(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT NOT NULL,student_id INT NOT NULL,start_time DATETIME NOT NULL,submit_time DATETIME,status ENUM('started','submitted','auto_submitted') DEFAULT 'started',total_marks DECIMAL(7,2) DEFAULT 0,obtained_marks DECIMAL(7,2) DEFAULT 0,UNIQUE(exam_id,student_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE student_answers(id INT AUTO_INCREMENT PRIMARY KEY,attempt_id INT NOT NULL,question_id INT NOT NULL,selected_option_id INT,answer_text TEXT,obtained_marks DECIMAL(5,2) DEFAULT 0,evaluation_status ENUM('pending','auto_evaluated','ai_evaluated','manually_evaluated') DEFAULT 'pending',UNIQUE(attempt_id,question_id),FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,FOREIGN KEY(selected_option_id) REFERENCES question_options(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE results(id INT AUTO_INCREMENT PRIMARY KEY,attempt_id INT UNIQUE NOT NULL,student_id INT NOT NULL,exam_id INT NOT NULL,total_marks DECIMAL(7,2),obtained_marks DECIMAL(7,2),percentage DECIMAL(5,2),grade VARCHAR(10),result_status ENUM('pass','fail'),FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE proctoring_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,attempt_id INT NOT NULL,student_id INT NOT NULL,event_type ENUM('face_missing','multiple_faces','camera_off','tab_switch','fullscreen_exit','looking_away','phone_detected','unknown_object','audio_detected','suspicious_activity') NOT NULL,event_message VARCHAR(500),face_count INT DEFAULT 0,risk_level ENUM('low','medium','high','critical') DEFAULT 'low',event_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE proctoring_snapshots(id BIGINT AUTO_INCREMENT PRIMARY KEY,attempt_id INT NOT NULL,student_id INT NOT NULL,log_id BIGINT,image_path VARCHAR(500) NOT NULL,captured_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(log_id) REFERENCES proctoring_logs(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE ai_evaluations(id BIGINT AUTO_INCREMENT PRIMARY KEY,answer_id INT UNIQUE NOT NULL,expected_answer TEXT,student_answer TEXT,ai_score DECIMAL(5,2) DEFAULT 0,feedback TEXT,confidence DECIMAL(5,2) DEFAULT 0,evaluated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(answer_id) REFERENCES student_answers(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE performance_analysis(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,exam_id INT NOT NULL,accuracy DECIMAL(5,2),average_time_seconds INT,strong_area TEXT,weak_area TEXT,ai_feedback TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE ai_proctoring_summary(id BIGINT AUTO_INCREMENT PRIMARY KEY,attempt_id INT UNIQUE NOT NULL,student_id INT NOT NULL,total_events INT DEFAULT 0,low_events INT DEFAULT 0,medium_events INT DEFAULT 0,high_events INT DEFAULT 0,critical_events INT DEFAULT 0,risk_score DECIMAL(5,2) DEFAULT 0,final_status ENUM('normal','suspicious','high_risk') DEFAULT 'normal',ai_summary TEXT,generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE login_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100),ip_address VARCHAR(45),success TINYINT(1) DEFAULT 0,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(username,attempted_at),INDEX(ip_address,attempted_at)) ENGINE=InnoDB;
